/**
 * Daily-life guidance quoted under reminders (Canvas `Extra: verse | hadith | both | off`).
 *
 * Content is a curated list (extras-data.ts, generated by scripts/build-extras.ts):
 *   verses -> Arabic + Urdu      hadith -> Urdu only
 * A random pick from the whole Qur'an / hadith books can't guarantee "guidance for daily life" and
 * often reads oddly out of context in a work channel — so nothing is fetched at reminder time.
 *
 * Selection is a deterministic rotation by date + prayer slot: no repeats within a day, the whole
 * list cycles over the days, and a DRY_RUN shows exactly what the real run will post.
 */
import type { Extra, ExtraKind } from "./types";
import { EXTRA_HADITH, EXTRA_VERSES } from "./extras-data";

/** Upper bound on prayers per day used to space out the rotation. */
const SLOTS_PER_DAY = 5;

/**
 * @param dateKey local date "YYYY-MM-DD"
 * @param slot    position of the prayer among today's enabled prayers (0-based)
 */
export function pickExtra(
  kind: ExtraKind,
  dateKey: string,
  slot: number,
  lists: { verses: Extra[]; hadith: Extra[] } = { verses: EXTRA_VERSES, hadith: EXTRA_HADITH },
): Extra | null {
  if (kind === "off") return null;
  const day = dayNumber(dateKey);
  if (day === null) return null;

  // "both" alternates verse / hadith across the day's prayers (and flips each day).
  const which = kind === "both" ? ((day + slot) % 2 === 0 ? "verse" : "hadith") : kind;
  const list = which === "verse" ? lists.verses : lists.hadith;
  if (list.length === 0) return null;

  const turn = kind === "both" ? Math.floor((day * SLOTS_PER_DAY + slot) / 2) : day * SLOTS_PER_DAY + slot;
  return list[turn % list.length]!;
}

/** Days since 1970-01-01 for a "YYYY-MM-DD" key, or null if malformed. */
function dayNumber(dateKey: string): number | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateKey);
  if (!m) return null;
  return Math.floor(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / 86_400_000);
}
